-- [S4] Parent company as each program records it: GHGRP facility (by FRS_ID) and TRI facility (by FRS_ID / EPA_REGISTRY_ID)
SELECT 'GHGRP' AS SRC, TO_VARCHAR(FRS_ID) AS REG, FACILITY_NAME AS NM, CITY, STATE AS ST, PARENT_COMPANY AS PARENT, MIN(REPORTING_YEAR)::VARCHAR AS Y0, MAX(REPORTING_YEAR)::VARCHAR AS Y1, COUNT(*) AS N
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_GHGRP_FACILITY WHERE TO_VARCHAR(FRS_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602') GROUP BY 1,2,3,4,5,6
UNION ALL
SELECT 'TRI', COALESCE(TO_VARCHAR(FRS_ID), TO_VARCHAR(EPA_REGISTRY_ID)), FACILITY_NAME, CITY_NAME, STATE_ABBR, COALESCE(STANDARDIZED_PARENT_COMPANY, PARENT_CO_NAME) || ' / DB ' || COALESCE(PARENT_CO_DB_NUM,'-'), TRI_FACILITY_ID, FAC_CLOSED_IND, COUNT(*)
FROM LIBRARY_MARTS.ENVIRONMENT.ENVIRONMENT__FED_EPA_TRI_FACILITY WHERE TO_VARCHAR(FRS_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602') OR TO_VARCHAR(EPA_REGISTRY_ID) IN ('110017404548','110005972821','110041204265','110020497121','110000448043','110000448472','110000596793','110030484107','110022409883','110037424533','110000606504','110031127126','110040499449','110070005201','110030917603','110029535171','110000615503','110001505602') GROUP BY 1,2,3,4,5,6,7,8
ORDER BY 2,1
